function validate(input) {
  const [{ Delivery = [] }] = input;
  const ids = new Set(), earliest = new Map();
  for (const row of Delivery) {
    if (row.some((v) => v === null)) return 'Delivery rows may not contain null.';
    const [id, customer, ordered, preferred] = row;
    if (ids.has(id)) return `delivery_id ${id} appears twice in Delivery.`;
    ids.add(id);
    if (preferred < ordered) return `Delivery ${id} prefers a date before its order date.`;
    const seen = earliest.get(customer);
    if (!seen || ordered < seen.date) earliest.set(customer, { date: ordered, count: 1 });
    else if (ordered === seen.date) seen.count++;
  }
  for (const [customer, { count }] of earliest) if (count > 1) return `Customer ${customer} has two first orders.`;
  return null;
}

