function generate(rand, size) {
  const day = (n) => new Date(Date.UTC(2019, 7, 1 + n)).toISOString().slice(0, 10);
  const small = size === 'small';
  const customers = small ? Math.floor(rand() * 5) : 500;
  const limit = small ? 8 : 2000;
  const orders = [];
  for (let customer = 1; customer <= customers && orders.length < limit; customer++) {
    // The first order sits alone on the customer's earliest date; later orders may share dates.
    const first = Math.floor(rand() * (small ? 5 : 60));
    const lag = () => (rand() < 0.5 ? 0 : 1 + Math.floor(rand() * 3));
    orders.push([customer, day(first), day(first + lag())]);
    const extra = Math.floor(rand() * (small ? 3 : 7));
    for (let k = 0; k < extra && orders.length < limit; k++) {
      const date = first + 1 + Math.floor(rand() * (small ? 3 : 30));
      orders.push([customer, day(date), day(date + lag())]);
    }
  }
  // Shuffle so that delivery_id order says nothing about which order came first.
  for (let i = orders.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [orders[i], orders[j]] = [orders[j], orders[i]];
  }
  const Delivery = orders.map(([customer, ordered, preferred], i) => [i + 1, customer, ordered, preferred]);
  return [{ Delivery }];
}
